import{_ as a,o as e,c as r,a0 as o}from"./chunks/framework.B7o6dWmz.js";const u=JSON.parse('{"title":"定价与毛利","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/guide/pricing.md","filePath":"zh-Hans/guide/pricing.md","lastUpdated":1793979958000}'),n={name:"zh-Hans/guide/pricing.md"};function i(d,t,l,s,h,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="定价与毛利" tabindex="-1">定价与毛利 <a class="header-anchor" href="#定价与毛利" aria-label="Permalink to &quot;定价与毛利&quot;">​</a></h1><p>NetonAPI 的定价只有一个锚点：<strong>官方价</strong>。所有价格都写成「官方价的多少」，客户好比价，运营好算账。</p><h2 id="用户看到的价格怎么来" tabindex="-1">用户看到的价格怎么来 <a class="header-anchor" href="#用户看到的价格怎么来" aria-label="Permalink to &quot;用户看到的价格怎么来&quot;">​</a></h2><p>一个用户调用某个模型时，价格按下面顺序找，找到哪层就用哪层：</p><table tabindex="0"><thead><tr><th>层级</th><th>什么时候用</th><th>写法</th></tr></thead><tbody><tr><td>协议价</td><td>运营给<strong>这个用户</strong>单独谈了这个模型</td><td>官方价 N 折，例如 85 折</td></tr><tr><td>分组价</td><td>他的 API Key 属于某个计费分组（如企业客户、专线）</td><td>分组倍率，或分组里按模型定价</td></tr><tr><td>全站价</td><td>以上都没有</td><td>官方价 × 全站加价率（也可以给某个模型单独设）</td></tr></tbody></table><p>用户在控制台「模型与价格」里能看到每个模型自己的价格、相当于官方价几折、是不是协议价； 运营在后台「协议定价」里能看到这个用户每个模型的价格来自哪一层。</p><h2 id="一个例子" tabindex="-1">一个例子 <a class="header-anchor" href="#一个例子" aria-label="Permalink to &quot;一个例子&quot;">​</a></h2><p>假设 Claude Sonnet 官方价是输入 $3 / 输出 $15（每百万 tokens），全站加价率 1.0（按官方价卖）：</p><ul><li>普通用户：输入 $3、输出 $15。</li><li>企业分组倍率 0.95：输入 $2.85、输出 $14.25。</li><li>给大客户 Acme 谈了 85 折协议价：输入 $2.55、输出 $12.75。</li></ul><p>Acme 调用一次，输入 10,000 tokens、输出 2,000 tokens，扣费就是 <code>10,000 × 2.55 / 1,000,000 + 2,000 × 12.75 / 1,000,000 = $0.051</code>，和他在控制台看到的单价一算就对得上。</p><h2 id="为什么不会卖亏" tabindex="-1">为什么不会卖亏 <a class="header-anchor" href="#为什么不会卖亏" aria-label="Permalink to &quot;为什么不会卖亏&quot;">​</a></h2><p>每条上游渠道都记着自己的拿货价，例如「OpenAI 官方 82 折」「合作中转站 55 折」。 保存任何价格前（全站价、分组价、协议价），NetonAPI 都会把这个价格放到<strong>真实会走的每条渠道</strong>上算一遍毛利：</p><ul><li>低于成本：保存不了，提示是哪个分组、哪条渠道、哪一项亏了；</li><li>低于你设的最低毛利：同样拒绝。</li></ul><p>如果上面的例子里承载 Claude 的渠道拿货价是 9 折，那 85 折的协议价就保存不了——要么换更便宜的渠道，要么少打点折。</p><p>「模型定价」列表会直接显示每个模型在所有「分组 × 渠道」组合里的<strong>最差毛利</strong>，亏本标红；概览页按分组、渠道统计收入、成本与毛利。</p><h2 id="官方价变了怎么办" tabindex="-1">官方价变了怎么办 <a class="header-anchor" href="#官方价变了怎么办" aria-label="Permalink to &quot;官方价变了怎么办&quot;">​</a></h2><p>NetonAPI 定时从公开价源（默认与 new-api 同源，也可换 models.dev、LiteLLM、OpenRouter）拉取最新官方价， 逐个列出涨跌，由运营确认后应用。因为所有价格都是「官方价的多少」，官方价一更新，全站价、分组价、协议价都会自动跟着走， 给客户的「85 折」承诺一直成立。</p><h2 id="一些细节" tabindex="-1">一些细节 <a class="header-anchor" href="#一些细节" aria-label="Permalink to &quot;一些细节&quot;">​</a></h2><ul><li><strong>缓存</strong>：缓存读写分别计价；上游没给缓存价时按输入价计，不会白送缓存命中。</li><li><strong>按次、长上下文</strong>：图片等模型可以按次计价；长上下文模型支持按输入长度分档。</li><li><strong>账务</strong>：每次请求先按上限预留额度，结束后按实际用量结算，定价快照随请求冻结，中途改价不影响在途请求。</li><li><strong>调价记录</strong>：每一次改价都记下谁、什么时候、从多少改成多少。</li></ul>',19)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
